// Package lg implements a small terminal layout toolkit: ANSI aware string
// measurement, word wrapping, block styling, joining and tables.
package lg

import (
	"github.com/rivo/uniseg"
)

const esc = 0x1b

// seqKind classifies a decoded token.
type seqKind int

const (
	kindPrint   seqKind = iota // printable ASCII
	kindControl                // C0 control / DEL / stray byte
	kindEscape                 // escape sequence
	kindCluster                // multi-byte grapheme cluster
)

// token describes the next unit of a string.
type token struct {
	seq   string
	width int
	kind  seqKind
	// for CSI sequences
	csiFinal  byte
	csiParams string
}

// escapeLen returns the byte length of the escape sequence starting at s[0]
// (which must be ESC).
func escapeLen(s string) (n int, isCSI bool, final byte, params string) {
	if len(s) < 2 {
		return len(s), false, 0, ""
	}
	switch s[1] {
	case '[':
		i := 2
		for i < len(s) && s[i] >= 0x30 && s[i] <= 0x3f {
			i++
		}
		pend := i
		for i < len(s) && s[i] >= 0x20 && s[i] <= 0x2f {
			i++
		}
		if i < len(s) && s[i] >= 0x40 && s[i] <= 0x7e {
			return i + 1, true, s[i], s[2:pend]
		}
		// Unterminated or invalid; consume what we have up to an invalid byte.
		if i < len(s) {
			return i, false, 0, ""
		}
		return len(s), false, 0, ""
	case ']', 'P', 'X', '^', '_':
		i := 2
		for i < len(s) {
			if s[i] == 0x07 && s[1] == ']' {
				return i + 1, false, 0, ""
			}
			if s[i] == esc && i+1 < len(s) && s[i+1] == '\\' {
				return i + 2, false, 0, ""
			}
			i++
		}
		return len(s), false, 0, ""
	default:
		i := 1
		for i < len(s) && s[i] >= 0x20 && s[i] <= 0x2f {
			i++
		}
		if i < len(s) && s[i] >= 0x30 && s[i] <= 0x7e {
			return i + 1, false, 0, ""
		}
		if i < len(s) {
			return i, false, 0, ""
		}
		return len(s), false, 0, ""
	}
}

// nextToken decodes the next token from s.
func nextToken(s string) token {
	c := s[0]
	if c == esc {
		n, isCSI, final, params := escapeLen(s)
		if n < 1 {
			n = 1
		}
		t := token{seq: s[:n], kind: kindEscape}
		if isCSI {
			t.csiFinal = final
			t.csiParams = params
		}
		return t
	}
	if c > 0x1f && c < 0x7f {
		return token{seq: s[:1], width: 1, kind: kindPrint}
	}
	if c < 0xc0 {
		return token{seq: s[:1], kind: kindControl}
	}
	cluster, _, w, _ := uniseg.FirstGraphemeClusterInString(s, -1)
	if len(cluster) == 0 {
		return token{seq: s[:1], kind: kindControl}
	}
	return token{seq: cluster, width: w, kind: kindCluster}
}

// Width returns the printable cell width of the widest line in s.
func Width(s string) int {
	w := 0
	start := 0
	for i := 0; i <= len(s); i++ {
		if i == len(s) || s[i] == '\n' {
			lw := StringWidth(s[start:i])
			if lw > w {
				w = lw
			}
			start = i + 1
		}
	}
	return w
}

// StringWidth returns the printable cell width of s, ignoring escape
// sequences and control characters.
func StringWidth(s string) int {
	w := 0
	for len(s) > 0 {
		t := nextToken(s)
		w += t.width
		s = s[len(t.seq):]
	}
	return w
}

// Height returns the number of lines in s.
func Height(s string) int {
	n := 1
	for i := 0; i < len(s); i++ {
		if s[i] == '\n' {
			n++
		}
	}
	return n
}

// Truncate truncates s so that its printable width doesn't exceed length,
// keeping escape sequences.
func Truncate(s string, length int) string {
	if StringWidth(s) <= length {
		return s
	}
	if length < 0 {
		return ""
	}
	var b []byte
	cur := 0
	ignoring := false
	for len(s) > 0 {
		t := nextToken(s)
		s = s[len(t.seq):]
		switch t.kind {
		case kindEscape, kindControl:
			b = append(b, t.seq...)
		default:
			if ignoring {
				continue
			}
			if cur+t.width > length {
				ignoring = true
				continue
			}
			cur += t.width
			b = append(b, t.seq...)
		}
	}
	return string(b)
}
EOF
echo ok"}

