package lg

import (
	"strconv"
	"strings"
)

// colorSpec is a parsed SGR color.
type colorSpec struct {
	set  bool
	kind int // 0 basic (0-15), 1 extended (256), 2 rgb
	n    int
	r, g, b int
}

func (c colorSpec) seq(base int) string {
	// base: 30 for fg, 40 for bg, 50 for underline color
	switch c.kind {
	case 0:
		if base == 50 {
			return "58;5;" + strconv.Itoa(c.n)
		}
		if c.n < 8 {
			return strconv.Itoa(base + c.n)
		}
		return strconv.Itoa(base + 60 + c.n - 8)
	case 1:
		return strconv.Itoa(base+8) + ";5;" + strconv.Itoa(c.n)
	default:
		return strconv.Itoa(base+8) + ";2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
	}
}

const (
	attrBold = 1 << iota
	attrFaint
	attrItalic
	attrSlowBlink
	attrRapidBlink
	attrReverse
	attrConceal
	attrStrike
)

// pen tracks the current SGR state.
type pen struct {
	attrs   int
	ul      int // underline style, 0 none
	fg, bg  colorSpec
	ulColor colorSpec
}

func (p *pen) empty() bool {
	return p.attrs == 0 && p.ul == 0 && !p.fg.set && !p.bg.set && !p.ulColor.set
}

func (p *pen) reset() { *p = pen{} }

func (p *pen) sequence() string {
	if p.empty() {
		return "\x1b[m"
	}
	var parts []string
	if p.attrs&attrBold != 0 {
		parts = append(parts, "1")
	}
	if p.attrs&attrFaint != 0 {
		parts = append(parts, "2")
	}
	if p.attrs&attrItalic != 0 {
		parts = append(parts, "3")
	}
	if p.attrs&attrSlowBlink != 0 {
		parts = append(parts, "5")
	}
	if p.attrs&attrRapidBlink != 0 {
		parts = append(parts, "6")
	}
	if p.attrs&attrReverse != 0 {
		parts = append(parts, "7")
	}
	if p.attrs&attrConceal != 0 {
		parts = append(parts, "8")
	}
	if p.attrs&attrStrike != 0 {
		parts = append(parts, "9")
	}
	switch p.ul {
	case 1:
		parts = append(parts, "4")
	case 2:
		parts = append(parts, "4:2")
	case 3:
		parts = append(parts, "4:3")
	case 4:
		parts = append(parts, "4:4")
	case 5:
		parts = append(parts, "4:5")
	}
	if p.fg.set {
		parts = append(parts, p.fg.seq(30))
	}
	if p.bg.set {
		parts = append(parts, p.bg.seq(40))
	}
	if p.ulColor.set {
		parts = append(parts, p.ulColor.seq(50))
	}
	return "\x1b[" + strings.Join(parts, ";") + "m"
}

type sgrParam struct {
	v       int
	hasMore bool // followed by ':' sub-parameter
}

func parseSGRParams(s string) []sgrParam {
	if s == "" {
		return nil
	}
	var out []sgrParam
	cur := -1
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= '0' && c <= '9':
			if cur < 0 {
				cur = 0
			}
			cur = cur*10 + int(c-'0')
		case c == ';' || c == ':':
			v := cur
			if v < 0 {
				v = 0
			}
			out = append(out, sgrParam{v: v, hasMore: c == ':'})
			cur = -1
		default:
			// ignore other bytes
		}
	}
	v := cur
	if v < 0 {
		v = 0
	}
	out = append(out, sgrParam{v: v})
	return out
}

// readColor reads an extended color starting at params[i] (which is 38/48/58).
// It returns the color and the number of params consumed (including the first).
func readColor(params []sgrParam, i int) (colorSpec, int) {
	if i+1 >= len(params) {
		return colorSpec{}, 1
	}
	switch params[i+1].v {
	case 5:
		if i+2 < len(params) {
			return colorSpec{set: true, kind: 1, n: params[i+2].v & 0xff}, 3
		}
		return colorSpec{}, 2
	case 2:
		if i+4 < len(params) {
			return colorSpec{set: true, kind: 2, r: params[i+2].v & 0xff, g: params[i+3].v & 0xff, b: params[i+4].v & 0xff}, 5
		}
		return colorSpec{}, len(params) - i
	}
	return colorSpec{}, 2
}

func (p *pen) apply(paramStr string) {
	params := parseSGRParams(paramStr)
	if len(params) == 0 {
		p.reset()
		return
	}
	for i := 0; i < len(params); i++ {
		param := params[i]
		switch v := param.v; {
		case v == 0:
			p.reset()
		case v == 1:
			p.attrs |= attrBold
		case v == 2:
			p.attrs |= attrFaint
		case v == 3:
			p.attrs |= attrItalic
		case v == 4:
			if param.hasMore && i+1 < len(params) {
				n := params[i+1].v
				if n <= 5 {
					i++
					p.ul = n
					continue
				}
			}
			p.ul = 1
		case v == 5:
			p.attrs |= attrSlowBlink
		case v == 6:
			p.attrs |= attrRapidBlink
		case v == 7:
			p.attrs |= attrReverse
		case v == 8:
			p.attrs |= attrConceal
		case v == 9:
			p.attrs |= attrStrike
		case v == 22:
			p.attrs &^= attrBold | attrFaint
		case v == 23:
			p.attrs &^= attrItalic
		case v == 24:
			p.ul = 0
		case v == 25:
			p.attrs &^= attrSlowBlink | attrRapidBlink
		case v == 27:
			p.attrs &^= attrReverse
		case v == 28:
			p.attrs &^= attrConceal
		case v == 29:
			p.attrs &^= attrStrike
		case v >= 30 && v <= 37:
			p.fg = colorSpec{set: true, n: v - 30}
		case v == 38:
			c, n := readColor(params, i)
			if c.set {
				p.fg = c
			}
			i += n - 1
		case v == 39:
			p.fg = colorSpec{}
		case v >= 40 && v <= 47:
			p.bg = colorSpec{set: true, n: v - 40}
		case v == 48:
			c, n := readColor(params, i)
			if c.set {
				p.bg = c
			}
			i += n - 1
		case v == 49:
			p.bg = colorSpec{}
		case v == 58:
			c, n := readColor(params, i)
			if c.set {
				p.ulColor = c
			}
			i += n - 1
		case v == 59:
			p.ulColor = colorSpec{}
		case v >= 90 && v <= 97:
			p.fg = colorSpec{set: true, n: v - 90 + 8}
		case v >= 100 && v <= 107:
			p.bg = colorSpec{set: true, n: v - 100 + 8}
		}
	}
}
EOF
echo ok"}

