func WrapRender(s string, limit int) string {
	if len(s) == 0 {
		return ""
	}
	if limit < 1 {
		return s
	}

	var (
		buf, word, space strings.Builder
		style, curStyle  pen
		linkURL, linkPrm string
		curURL, curPrm   string
		curWidth         int
		wordLen          int
