			buf.WriteString("\x1b]8;;\x07")
		}
		buf.WriteByte('\n')
		if curURL != "" || curPrm != "" {
			buf.WriteString("\x1b]8;" + curPrm + ";" + curURL + "\x07")
		}
		if !curStyle.empty() {
			buf.WriteString(curStyle.sequence())
		}
		curWidth = 0
		space.Reset()
	}

