		t := nextToken(s)
		s = s[len(t.seq):]
		if t.width == 0 {
			switch {
			case t.seq == "\t":
				addWord()
				space.WriteString(t.seq)
				continue
			case t.seq == "\n":
				if wordLen == 0 {
