package lg

import (
	"strings"
)

// ColorEnabled controls whether styles emit ANSI escape sequences.
var ColorEnabled = true

// Position is a horizontal alignment.
type Position int

const (
	Left Position = iota
	Center
	Right
)

// Border holds the runes used to draw a border.
type Border struct {
	Top          string
	Bottom       string
	Left         string
	Right        string
	TopLeft      string
	TopRight     string
	BottomLeft   string
	BottomRight  string
	MiddleLeft   string
	MiddleRight  string
	Middle       string
	MiddleTop    string
	MiddleBottom string
}

var (
	NormalBorder = Border{
		Top: "─", Bottom: "─", Left: "│", Right: "│",
		TopLeft: "┌", TopRight: "┐", BottomLeft: "└", BottomRight: "┘",
		MiddleLeft: "├", MiddleRight: "┤", Middle: "┼", MiddleTop: "┬", MiddleBottom: "┴",
	}
	RoundedBorder = Border{
		Top: "─", Bottom: "─", Left: "│", Right: "│",
		TopLeft: "╭", TopRight: "╮", BottomLeft: "╰", BottomRight: "╯",
		MiddleLeft: "├", MiddleRight: "┤", Middle: "┼", MiddleTop: "┬", MiddleBottom: "┴",
	}
	ThickBorder = Border{
		Top: "━", Bottom: "━", Left: "┃", Right: "┃",
		TopLeft: "┏", TopRight: "┓", BottomLeft: "┗", BottomRight: "┛",
		MiddleLeft: "┣", MiddleRight: "┫", Middle: "╋", MiddleTop: "┳", MiddleBottom: "┻",
	}
	HiddenBorder = Border{
		Top: " ", Bottom: " ", Left: " ", Right: " ",
		TopLeft: " ", TopRight: " ", BottomLeft: " ", BottomRight: " ",
		MiddleLeft: " ", MiddleRight: " ", Middle: " ", MiddleTop: " ", MiddleBottom: " ",
	}
	MarkdownBorder = Border{
		Top: "-", Bottom: "-", Left: "|", Right: "|",
		TopLeft: "|", TopRight: "|", BottomLeft: "|", BottomRight: "|",
		MiddleLeft: "|", MiddleRight: "|", Middle: "|", MiddleTop: "|", MiddleBottom: "|",
	}
)

// Style describes how a block of text is rendered.
type Style struct {
	set bool

	fg    string // SGR parameter for the foreground color
	faint bool

	width, height       int
	maxWidth, maxHeight int

	padTop, padRight, padBottom, padLeft int

	align Position

	border                                     *Border
	borderTop, borderRight, borderBottom, borderLeft int // 0 unset, 1 on, 2 off
	borderFg                                   string
}

// NewStyle returns an empty style.
func NewStyle() Style { return Style{} }

func (s Style) Foreground(seq string) Style { s.set = true; s.fg = seq; return s }
func (s Style) Faint(v bool) Style           { s.set = true; s.faint = v; return s }
func (s Style) Width(w int) Style            { s.set = true; s.width = w; return s }
func (s Style) Height(h int) Style           { s.set = true; s.height = h; return s }
func (s Style) MaxWidth(w int) Style         { s.set = true; s.maxWidth = w; return s }
func (s Style) MaxHeight(h int) Style        { s.set = true; s.maxHeight = h; return s }
func (s Style) Align(p Position) Style       { s.set = true; s.align = p; return s }
func (s Style) Padding(v, h int) Style {
	s.set = true
	s.padTop, s.padBottom = v, v
	s.padLeft, s.padRight = h, h
	return s
}
func (s Style) BorderStyle(b Border) Style { s.set = true; s.border = &b; return s }
func (s Style) BorderTop(v bool) Style     { s.set = true; s.borderTop = flag(v); return s }
func (s Style) BorderForeground(seq string) Style {
	s.set = true
	s.borderFg = seq
	return s
}

func flag(v bool) int {
	if v {
		return 1
	}
	return 2
}

// HorizontalPadding returns left+right padding.
func (s Style) HorizontalPadding() int { return s.padLeft + s.padRight }

// Styled wraps str in the given SGR sequence if colors are enabled.
func Styled(seq, str string) string {
	if !ColorEnabled || seq == "" {
		return str
	}
	return "\x1b[" + seq + "m" + str + "\x1b[0m"
}

func convertTabs(s string) string {
	return strings.ReplaceAll(s, "\t", "    ")
}

func (s Style) textSeq() string {
	var parts []string
	if s.faint {
		parts = append(parts, "2")
	}
	if s.fg != "" {
		parts = append(parts, s.fg)
	}
	return strings.Join(parts, ";")
}

// Render renders str with the style.
func (s Style) Render(str string) string {
	if !s.set {
		return convertTabs(str)
	}
	seq := s.textSeq()

	str = convertTabs(str)
	str = strings.ReplaceAll(str, "\r\n", "\n")

	if s.width > 0 {
		wrapAt := s.width - s.padLeft - s.padRight
		str = WrapRender(str, wrapAt)
	}

	// Render core text.
	{
		lines := strings.Split(str, "\n")
		var b strings.Builder
		for i, l := range lines {
			b.WriteString(Styled(seq, l))
			if i != len(lines)-1 {
				b.WriteByte('\n')
			}
