		str = b.String()
	}

	// Padding.
	if s.padLeft > 0 {
		str = padLines(str, strings.Repeat(" ", s.padLeft), true)
	}
	if s.padRight > 0 {
		str = padLines(str, strings.Repeat(" ", s.padRight), false)
	}
	if s.padTop > 0 {
		str = strings.Repeat("\n", s.padTop) + str
	}
	if s.padBottom > 0 {
		str += strings.Repeat("\n", s.padBottom)
	}

