func padLines(str, pad string, left bool) string {
	lines := strings.Split(str, "\n")
	for i := range lines {
		if left {
			lines[i] = pad + lines[i]
		} else {
			lines[i] = lines[i] + pad
		}
	}
	return strings.Join(lines, "\n")
}

func getLines(s string) ([]string, int) {
	lines := strings.Split(s, "\n")
	widest := 0
	for _, l := range lines {
		if w := StringWidth(l); w > widest {
