func alignHorizontal(str string, pos Position, width int) string {
	lines, widest := getLines(str)
	var b strings.Builder
	for i, l := range lines {
		lw := StringWidth(l)
		short := widest - lw
		if rest := width - (short + lw); rest > 0 {
			short += rest
		}
		if short > 0 {
			switch pos {
			case Right:
				l = strings.Repeat(" ", short) + l
			case Center:
				left := short / 2
				right := left + short%2
				l = strings.Repeat(" ", left) + l + strings.Repeat(" ", right)
			default:
				l += strings.Repeat(" ", short)
			}
		}
		b.WriteString(l)
		if i < len(lines)-1 {
			b.WriteByte('\n')
		}
	}
	return b.String()
}

func firstRune(s string) string {
	for _, r := range s {
