		switch {
		case !hasLeft && !hasRight:
			border.BottomLeft, border.BottomRight = "", ""
		case !hasLeft:
			border.BottomLeft = ""
		case !hasRight:
			border.BottomRight = ""
		}
	}
	border.TopLeft = firstRune(border.TopLeft)
	border.TopRight = firstRune(border.TopRight)
	border.BottomRight = firstRune(border.BottomRight)
	border.BottomLeft = firstRune(border.BottomLeft)

	var out strings.Builder
	if hasTop {
		top := renderHorizontalEdge(border.TopLeft, border.Top, border.TopRight, width)
		out.WriteString(Styled(s.borderFg, top))
		out.WriteByte('\n')
	}
	leftRunes := []rune(border.Left)
	rightRunes := []rune(border.Right)
	li, ri := 0, 0
	for i, l := range lines {
		if hasLeft {
			r := string(leftRunes[li])
			li++
			if li >= len(leftRunes) {
				li = 0
			}
			out.WriteString(Styled(s.borderFg, r))
		}
		out.WriteString(l)
		if hasRight {
			r := string(rightRunes[ri])
			ri++
			if ri >= len(rightRunes) {
				ri = 0
			}
			out.WriteString(Styled(s.borderFg, r))
		}
		if i < len(lines)-1 {
