func maxRuneWidth(s string) int {
	w := 0
	for _, r := range s {
		if rw := StringWidth(string(r)); rw > w {
			w = rw
		}
	}
	return w
}

func renderHorizontalEdge(left, middle, right string, width int) string {
	if middle == "" {
		middle = " "
	}
	leftWidth := StringWidth(left)
	rightWidth := StringWidth(right)
	runes := []rune(middle)
	j := 0
	var out strings.Builder
	out.WriteString(left)
	for i := leftWidth + rightWidth; i < width+rightWidth; {
		out.WriteRune(runes[j])
		j++
		if j >= len(runes) {
			j = 0
		}
		i += StringWidth(string(runes[j]))
	}
	out.WriteString(right)
	return out.String()
}

// JoinHorizontal joins blocks side by side, aligned to the top.
func JoinHorizontal(strs ...string) string {
	if len(strs) == 0 {
		return ""
	}
	if len(strs) == 1 {
		return strs[0]
	}
	blocks := make([][]string, len(strs))
	maxWidths := make([]int, len(strs))
	maxHeight := 0
	for i, s := range strs {
		blocks[i], maxWidths[i] = getLines(s)
		if len(blocks[i]) > maxHeight {
			maxHeight = len(blocks[i])
		}
	}
	for i := range blocks {
		for len(blocks[i]) < maxHeight {
			blocks[i] = append(blocks[i], "")
		}
	}
	var b strings.Builder
	for i := range blocks[0] {
		for j, block := range blocks {
			b.WriteString(block[i])
			if pad := maxWidths[j] - StringWidth(block[i]); pad > 0 {
				b.WriteString(strings.Repeat(" ", pad))
			}
		}
		if i < len(blocks[0])-1 {
			b.WriteByte('\n')
		}
	}
	return b.String()
}

// JoinVertical stacks blocks, aligned to the left.
func JoinVertical(strs ...string) string {
	if len(strs) == 0 {
		return ""
	}
	if len(strs) == 1 {
		return strs[0]
	}
	blocks := make([][]string, len(strs))
	maxWidth := 0
	for i, s := range strs {
		var w int
		blocks[i], w = getLines(s)
		if w > maxWidth {
			maxWidth = w
		}
	}
	var b strings.Builder
	for i, block := range blocks {
		for j, line := range block {
			b.WriteString(line)
			if pad := maxWidth - StringWidth(line); pad > 0 {
				b.WriteString(strings.Repeat(" ", pad))
			}
			if !(i == len(blocks)-1 && j == len(block)-1) {
				b.WriteByte('\n')
			}
		}
	}
	return b.String()
}
