	border       Border
	borderTop    bool
	borderBottom bool
	borderLeft   bool
	borderRight  bool
	borderHeader bool
	borderColumn bool

	headers   []string
	rows      [][]string
	styleFunc func(row, col int) Style

	widths  []int
	heights []int
}

// NewTable returns a table with rounded borders.
func NewTable() *Table {
	return &Table{
		border:       RoundedBorder,
		borderTop:    true,
		borderBottom: true,
		borderLeft:   true,
		borderRight:  true,
		borderHeader: true,
		borderColumn: true,
	}
}

func (t *Table) Border(b Border) *Table                          { t.border = b; return t }
func (t *Table) BorderTop(v bool) *Table                         { t.borderTop = v; return t }
func (t *Table) BorderBottom(v bool) *Table                      { t.borderBottom = v; return t }
func (t *Table) StyleFunc(f func(row, col int) Style) *Table     { t.styleFunc = f; return t }
func (t *Table) Headers(h ...string) *Table                      { t.headers = h; return t }
func (t *Table) Row(r ...string) *Table                          { t.rows = append(t.rows, r); return t }
func (t *Table) NumRows() int                                    { return len(t.rows) }

func (t *Table) style(row, col int) Style {
	if t.styleFunc == nil {
		return NewStyle()
	}
	return t.styleFunc(row, col)
}

func (t *Table) columns() int {
	n := len(t.headers)
	for _, r := range t.rows {
		if len(r) > n {
			n = len(r)
		}
	}
	return n
}

func (t *Table) cell(r, c int) string {
	if r < len(t.rows) && c < len(t.rows[r]) {
		return t.rows[r][c]
	}
	return ""
}

func (t *Table) resize() {
	hasHeaders := len(t.headers) > 0
	ncols := t.columns()
	var all [][]string
	if hasHeaders {
		all = append(all, t.headers)
	}
	for r := range t.rows {
		row := make([]string, ncols)
		for c := 0; c < ncols; c++ {
			row[c] = t.cell(r, c)
		}
		all = append(all, row)
	}

	maxw := make([]int, ncols)
	xpad := make([]int, ncols)
	for _, row := range all {
		for j, cell := range row {
			if w := Width(cell); w > maxw[j] {
				maxw[j] = w
			}
		}
	}
	for i, row := range all {
		ri := i
		if hasHeaders {
			ri--
		}
		for j := range row {
			st := t.style(ri, j)
			if p := st.HorizontalPadding(); p > xpad[j] {
				xpad[j] = p
			}
		}
	}
	t.widths = make([]int, ncols)
	for j := range t.widths {
		t.widths[j] = maxw[j] + xpad[j]
	}
	t.heights = make([]int, len(all))
	for i, row := range all {
		h := 1
		for j, cell := range row {
			ch := contentHeight(cell, t.widths[j]-xpad[j])
			if ch > h {
				h = ch
			}
		}
		t.heights[i] = h
	}
}

func contentHeight(content string, width int) int {
	if width == 0 {
		return 1
	}
	content = strings.ReplaceAll(content, "\r\n", "\n")
	h := 0
	for _, line := range strings.Split(content, "\n") {
		h += strings.Count(WrapMeasure(line, width), "\n") + 1
	}
	return h
}

func (t *Table) computeHeight() int {
	hasHeaders := len(t.headers) > 0
	sum := 0
	for _, h := range t.heights {
		sum += h
	}
	return sum - 1 + btoi(hasHeaders) + btoi(t.borderTop) + btoi(t.borderBottom) + btoi(t.borderHeader)
}

func btoi(b bool) int {
	if b {
		return 1
	}
	return 0
}

// String renders the table.
func (t *Table) String() string {
	hasHeaders := len(t.headers) > 0
	hasRows := len(t.rows) > 0
	if !hasHeaders && !hasRows {
		return ""
	}
	ncols := t.columns()
	if hasHeaders {
		for len(t.headers) < ncols {
			t.headers = append(t.headers, "")
		}
	}
	t.resize()

	var sb strings.Builder
	if t.borderTop {
		sb.WriteString(t.constructTopBorder())
		sb.WriteString("\n")
	}
	if hasHeaders {
		sb.WriteString(t.constructHeaders())
		sb.WriteString("\n")
	}
	var bottom string
	if t.borderBottom {
		bottom = t.constructBottomBorder()
	}
	for r := range t.rows {
		sb.WriteString(t.constructRow(r))
	}
	sb.WriteString(bottom)

	return NewStyle().MaxHeight(t.computeHeight()).Render(sb.String())
}

func (t *Table) constructTopBorder() string {
	var s strings.Builder
	if t.borderLeft {
		s.WriteString(t.border.TopLeft)
	}
	for i := range t.widths {
		s.WriteString(strings.Repeat(t.border.Top, t.widths[i]))
		if i < len(t.widths)-1 && t.borderColumn {
			s.WriteString(t.border.MiddleTop)
		}
	}
	if t.borderRight {
		s.WriteString(t.border.TopRight)
	}
	return s.String()
}

func (t *Table) constructBottomBorder() string {
	var s strings.Builder
	if t.borderLeft {
		s.WriteString(t.border.BottomLeft)
	}
	for i := range t.widths {
		s.WriteString(strings.Repeat(t.border.Bottom, t.widths[i]))
		if i < len(t.widths)-1 && t.borderColumn {
			s.WriteString(t.border.MiddleBottom)
		}
	}
	if t.borderRight {
		s.WriteString(t.border.BottomRight)
	}
	return s.String()
}

func (t *Table) renderCell(st Style, cell string, width, height int) string {
	return st.Height(height).MaxHeight(height).Width(width).MaxWidth(width).Render(cell)
}

func (t *Table) constructHeaders() string {
	height := t.heights[0]
	var s strings.Builder
	if t.borderLeft {
		s.WriteString(t.border.Left)
	}
	for i, header := range t.headers {
		st := t.style(HeaderRow, i)
		s.WriteString(t.renderCell(st, header, t.widths[i], height))
		if i < len(t.headers)-1 && t.borderColumn {
			s.WriteString(t.border.Left)
		}
	}
	if t.borderHeader {
		if t.borderRight {
			s.WriteString(t.border.Right)
		}
		s.WriteString("\n")
		if t.borderLeft {
			s.WriteString(t.border.MiddleLeft)
		}
		for i := range t.headers {
			s.WriteString(strings.Repeat(t.border.Top, t.widths[i]))
			if i < len(t.headers)-1 && t.borderColumn {
				s.WriteString(t.border.Middle)
			}
		}
		if t.borderRight {
			s.WriteString(t.border.MiddleRight)
		}
	}
	if t.borderRight && !t.borderHeader {
		s.WriteString(t.border.Right)
	}
	return s.String()
}

func (t *Table) constructRow(index int) string {
	hasHeaders := len(t.headers) > 0
	height := t.heights[index+btoi(hasHeaders)]
	ncols := t.columns()

	var cells []string
	left := strings.Repeat(t.border.Left+"\n", height)
	if t.borderLeft {
		cells = append(cells, left)
	}
	for c := 0; c < ncols; c++ {
		st := t.style(index, c)
		cells = append(cells, t.renderCell(st, t.cell(index, c), t.widths[c], height))
		if c < ncols-1 && t.borderColumn {
			cells = append(cells, left)
		}
	}
	if t.borderRight {
		cells = append(cells, strings.Repeat(t.border.Right+"\n", height))
	}
	for i, cell := range cells {
		cells[i] = strings.TrimRight(cell, "\n")
	}
	return JoinHorizontal(cells...) + "\n"
}
EOF
echo ok"}

