// Package parse reads go test -json event streams and summarizes them.
package parse

import (
	"regexp"
	"strconv"
	"strings"
	"time"
)

// Action is the action of a go test event.
type Action string

const (
	ActionRun    Action = "run"
	ActionPause  Action = "pause"
	ActionCont   Action = "cont"
	ActionPass   Action = "pass"
	ActionBench  Action = "bench"
	ActionFail   Action = "fail"
	ActionOutput Action = "output"
	ActionSkip   Action = "skip"
	ActionStart  Action = "start"
)

func (a Action) String() string { return string(a) }

// Event is a single line of go test -json output.
type Event struct {
	Time        time.Time
	Action      Action
	Package     string
	Test        string
	Elapsed     float64
	Output      string
	ImportPath  string
	FailedBuild string
}

// discardPrefixes are noisy updates that are never useful in a summary.
var discardPrefixes = []string{
	"=== RUN   ",
	"=== PAUSE ",
	"=== CONT  ",
}

// Discard reports whether the event is a noisy status update.
func (e *Event) Discard() bool {
	for _, p := range discardPrefixes {
		if strings.HasPrefix(e.Output, p) {
			return true
		}
	}
	return false
}

// noisy reports whether the event should be hidden when following output in
// non-verbose mode.
func (e *Event) noisy() bool {
	out := strings.TrimSpace(e.Output)
	if strings.HasPrefix(out, "--- PASS: ") || strings.HasPrefix(out, "--- SKIP: ") {
		return true
	}
	if e.Test == "" && (out == "PASS" || out == "FAIL") {
		return true
	}
	return false
}

// LastLine reports whether the event is the final summary line of a package.
func (e *Event) LastLine() bool {
	return e.Test == "" && e.Output == "" && (e.Action == ActionPass || e.Action == ActionFail)
}

// IsPanic reports whether the event marks the beginning of a panic.
func (e *Event) IsPanic() bool {
	return strings.HasPrefix(e.Output, "panic: ")
}

// IsRace reports whether the event marks a data race.
func (e *Event) IsRace() bool {
	return strings.HasPrefix(e.Output, "WARNING: DATA RACE")
}

// IsCached reports whether the package result was cached.
func (e *Event) IsCached() bool {
	return strings.HasPrefix(e.Output, "ok  \t") && strings.Contains(e.Output, "\t(cached)")
}

// NoTestFiles reports whether the package has no test files.
func (e *Event) NoTestFiles() bool {
	return strings.HasPrefix(e.Output, "?   \t") && strings.HasSuffix(e.Output, "[no test files]\n")
}

// NoTestsToRun reports whether the package had no tests to run.
func (e *Event) NoTestsToRun() bool {
	return strings.HasPrefix(e.Output, "ok  \t") && strings.HasSuffix(e.Output, "[no tests to run]\n")
}

// NoTestsWarn reports whether a test emitted the "no tests to run" warning.
func (e *Event) NoTestsWarn() bool {
	return e.Test != "" && e.Output == "testing: warning: no tests to run\n"
}

var coverRe = regexp.MustCompile(`[0-9]{1,3}\.[0-9]%`)

// Cover returns the coverage percentage reported by the event, if any.
func (e *Event) Cover() (float64, bool) {
	if !strings.Contains(e.Output, "coverage:") || !strings.Contains(e.Output, "of statements") {
		return 0, false
	}
	m := coverRe.FindString(e.Output)
	if m == "" {
		return 0, false
	}
	f, err := strconv.ParseFloat(strings.TrimSuffix(m, "%"), 64)
	if err != nil {
		return 0, false
	}
	return f, true
}
EOF
cat > /workspace/internal/parse/package.go <<'EOF'
package parse

import (
	"sort"
	"strings"
)

// Test is a single test and all of its events.
type Test struct {
	Name    string
	Package string
	Events  []*Event
}

// SortEvents sorts the events of the test by time.
func (t *Test) SortEvents() {
	sort.Slice(t.Events, func(i, j int) bool {
		return t.Events[i].Time.Before(t.Events[j].Time)
	})
}

// Status returns the final status of the test.
func (t *Test) Status() Action {
	t.SortEvents()
	for i := len(t.Events) - 1; i >= 0; i-- {
		switch t.Events[i].Action {
		case ActionPass, ActionFail, ActionSkip:
			return t.Events[i].Action
		}
	}
	return ActionFail
}

// Elapsed returns the elapsed time of the test in seconds.
func (t *Test) Elapsed() float64 {
	var f float64
	for _, e := range t.Events {
		if e.Elapsed > f {
			f = e.Elapsed
		}
	}
	return f
}

// Package is a summary of a single go package.
type Package struct {
	Summary *Event
	Tests   []*Test

	NoTestFiles bool
	NoTests     bool
	NoTestSlice []*Event

	HasPanic    bool
	PanicEvents []*Event

	HasDataRace bool
	Cached      bool

	Cover    bool
	Coverage float64
}

func newPackage() *Package {
	return &Package{Summary: &Event{}}
}

// AddTestEvent adds an event to the matching test, creating it if needed.
func (p *Package) AddTestEvent(e *Event) {
	for _, t := range p.Tests {
		if t.Name == e.Test {
			t.Events = append(t.Events, e)
			return
		}
	}
	p.Tests = append(p.Tests, &Test{Name: e.Test, Package: e.Package, Events: []*Event{e}})
}

// TestsByAction returns tests with the given final status, in order of
// appearance.
func (p *Package) TestsByAction(a Action) []*Test {
	var out []*Test
	for _, t := range p.Tests {
		if t.Status() == a {
			out = append(out, t)
		}
	}
	return out
}

// Base returns the top-level test name.
func Base(name string) string {
	if i := strings.Index(name, "/"); i >= 0 {
		return name[:i]
	}
	return name
}
EOF
echo ok"}

