// ErrNotParsable is returned when the input does not contain go test events.
var ErrNotParsable = errors.New("no parsable events: Make sure to run go test with -json flag")

const maxBadLines = 50

// Options configures Process.
type Options struct {
	Follow           bool
	FollowVerbose    bool
	FollowWriter     io.Writer
	IncludeTimestamp bool

	Progress       bool
	ProgressWriter io.Writer
	// StatusText colorizes a status for progress output.
	StatusText func(status string) string

	// Stderr receives build output.
	Stderr io.Writer
}

// Summary is the result of processing a go test event stream.
type Summary struct {
	Packages map[string]*Package
}

func (s *Summary) addEvent(e *Event) {
	if e.Discard() {
		return
	}
	pkg, ok := s.Packages[e.Package]
	if !ok {
		pkg = newPackage()
		s.Packages[e.Package] = pkg
	}
	if e.Action == ActionStart {
		return
	}
	if e.IsPanic() {
		pkg.HasPanic = true
		pkg.Summary.Action = ActionFail
		pkg.Summary.Package = e.Package
		pkg.Summary.Test = e.Test
	}
	if pkg.HasPanic {
		pkg.PanicEvents = append(pkg.PanicEvents, e)
		return
	}
	if e.LastLine() {
		pkg.Summary = e
		return
	}
	if e.IsRace() {
		pkg.HasDataRace = true
	}
	if e.IsCached() {
		pkg.Cached = true
	} else {
		if e.NoTestFiles() {
			pkg.NoTestFiles = true
			pkg.Summary.Package = e.Package
			pkg.Summary.Action = ActionPass
		}
		if e.NoTestsToRun() {
			pkg.NoTests = true
			pkg.Summary.Package = e.Package
			pkg.Summary.Action = ActionPass
		}
		if cover, ok := e.Cover(); ok {
			pkg.Cover = true
			pkg.Coverage = cover
		}
	}
	if e.NoTestsWarn() {
		pkg.NoTestSlice = append(pkg.NoTestSlice, e)
	}
	if e.Action == ActionOutput && e.Test == "" {
		return
	}
	pkg.AddTestEvent(e)
}

// ExitCode returns 1 if any package failed, panicked or raced.
func (s *Summary) ExitCode() int {
	for _, pkg := range s.Packages {
		if pkg.HasPanic || pkg.HasDataRace {
			return 1
		}
		if pkg.Summary.Action == ActionFail {
			return 1
		}
	}
	return 0
}

// Sorter orders packages.
type Sorter int

const (
	SortByName Sorter = iota
	SortByElapsed
	SortByCover
)

// SortedPackages returns all packages in the requested order.
func (s *Summary) SortedPackages(by Sorter) []*Package {
	keys := make([]string, 0, len(s.Packages))
	for k := range s.Packages {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	pkgs := make([]*Package, 0, len(keys))
	for _, k := range keys {
		pkgs = append(pkgs, s.Packages[k])
	}
	switch by {
	case SortByElapsed:
		sort.SliceStable(pkgs, func(i, j int) bool { return pkgs[i].Summary.Elapsed > pkgs[j].Summary.Elapsed })
	case SortByCover:
		sort.SliceStable(pkgs, func(i, j int) bool { return pkgs[i].Coverage > pkgs[j].Coverage })
	default:
		sort.SliceStable(pkgs, func(i, j int) bool { return pkgs[i].Summary.Package < pkgs[j].Summary.Package })
	}
	return pkgs
}

func writeFollow(w io.Writer, e *Event, ts bool) {
	if e.Output == "" {
		return
	}
	if ts {
		fmt.Fprint(w, e.Time.Format(time.RFC3339)+" "+e.Output)
		return
	}
	fmt.Fprint(w, e.Output)
}

// Process reads go test events from r.
func Process(r io.Reader, opts Options) (*Summary, error) {
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	summary := &Summary{Packages: make(map[string]*Package)}
	sc := bufio.NewScanner(r)
	var started bool
	var badLines int
	for sc.Scan() {
		e := new(Event)
		if err := json.Unmarshal(sc.Bytes(), e); err != nil {
			badLines++
			if started || badLines > maxBadLines {
				var syntaxErr *json.SyntaxError
				if errors.As(err, &syntaxErr) {
					return nil, ErrNotParsable
				}
				return nil, err
			}
			continue
		}
		started = true

		if opts.Follow && opts.FollowWriter != nil {
			if opts.FollowVerbose {
				writeFollow(opts.FollowWriter, e, opts.IncludeTimestamp)
			} else {
				if e.Discard() || e.noisy() {
					continue
				}
				writeFollow(opts.FollowWriter, e, opts.IncludeTimestamp)
			}
		}

		if e.ImportPath != "" {
			fmt.Fprint(opts.Stderr, e.Output)
			continue
		}

		summary.addEvent(e)

		if opts.Progress && opts.ProgressWriter != nil && e.LastLine() {
			pkg := summary.Packages[e.Package]
			status := e.Action.String()
			suffix := ""
			if pkg != nil {
				if pkg.NoTestFiles {
					status = "skip"
					suffix = " [no test files]"
				} else if pkg.NoTests {
					status = "skip"
					suffix = " [no tests to run]"
				}
			}
			text := toUpper(status)
			if opts.StatusText != nil {
				text = opts.StatusText(text)
			}
			elapsed := strconv.FormatFloat(e.Elapsed, 'f', 2, 64) + "s"
			fmt.Fprintf(opts.ProgressWriter, "[%s]\t%10s\t%s%s\n", text, elapsed, e.Package, suffix)
		}
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("received scanning error: %w", err)
	}
	if !started {
		return nil, ErrNotParsable
	}
	return summary, nil
}

func toUpper(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'a' && c <= 'z' {
			b[i] = c - 32
		}
	}
	return string(b)
}
