package app

import (
	"strings"

	"github.com/tparse-clone/tparse/internal/parse"
)

// namer computes display names for packages.
type namer struct {
	trimPath    string
	smallScreen bool
	common      string
}

func newNamer(packages []*parse.Package, trimPath string, smallScreen bool) *namer {
	n := &namer{trimPath: trimPath, smallScreen: smallScreen}
	if smallScreen || trimPath == "auto" {
		names := make([]string, 0, len(packages))
		for _, p := range packages {
			names = append(names, p.Summary.Package)
		}
		n.common = commonPrefix(names)
	}
	return n
}

func commonPrefix(names []string) string {
	if len(names) < 2 {
		return ""
	}
	prefix := names[0]
	for _, name := range names[1:] {
		i := 0
		for i < len(prefix) && i < len(name) && prefix[i] == name[i] {
			i++
		}
		prefix = prefix[:i]
		if prefix == "" {
			return ""
		}
	}
	if i := strings.LastIndex(prefix, "/"); i >= 0 {
		return prefix[:i+1]
	}
	return ""
}

func (n *namer) name(name string) string {
	if n.smallScreen {
		if n.trimPath != "" && n.trimPath != "auto" && strings.HasPrefix(name, n.trimPath) {
			return strings.TrimPrefix(strings.TrimPrefix(name, n.trimPath), "/")
		}
		if n.common != "" && strings.HasPrefix(name, n.common) {
			return strings.TrimPrefix(name, n.common)
		}
		if i := strings.LastIndex(name, "/"); i >= 0 {
			return name[i+1:]
		}
		return name
	}
	switch n.trimPath {
	case "":
		return name
	case "auto":
		if n.common != "" {
			return strings.TrimPrefix(name, n.common)
		}
		return name
	default:
		return strings.TrimPrefix(name, n.trimPath)
	}
}

// shortenTestName splits long test names on "/" so they fit on narrow
// screens.
func shortenTestName(name string) string {
	if len(name) <= 32 {
		return name
	}
	parts := strings.Split(name, "/")
	var b strings.Builder
	b.WriteString(parts[0])
	for _, p := range parts[1:] {
		b.WriteString("\n")
		prefix := " /"
		for len(p) > 32 {
			b.WriteString(prefix + p[:30] + " …\n")
			p = p[30:]
			prefix = "  "
		}
		b.WriteString(prefix + p)
	}
	return b.String()
}
EOF
