func (c *consoleWriter) summaryTable(packages []*parse.Package, showNoTests bool, n *namer, against *parse.Summary) {
	tbl := c.newTable(func(st lg.Style, row, col int) lg.Style {
		if row != lg.HeaderRow && col == 2 {
			st = st.Align(lg.Left)
		}
		return st
	})
