		if pkg.HasPanic {
			tbl.Row(c.red("PANIC"), elapsed, packageName, "--", "--", "--", "--")
			continue
		}
		if pkg.NoTestFiles {
			notests = append(notests, summaryRow{c.yellow("NOTEST"), elapsed, packageName + "\n[no test files]", "--", "--", "--", "--"})
			continue
		}
