			notests = append(notests, summaryRow{c.yellow("NOTEST"), elapsed, name, "--", "--", "--", "--"})
			if len(pkg.TestsByAction(parse.ActionPass)) == len(pkg.NoTestSlice) {
				continue
			}
		}
		if pkg.Cover && pkg.Coverage == 0 && len(pkg.Tests) == 0 {
			continue
		}
		coverage := "--"
		if pkg.Cover {
			coverage = fmt.Sprintf("%.1f%%", pkg.Coverage)
			if against != nil {
				if ap, ok := against.Packages[pkg.Summary.Package]; ok {
					diff := pkg.Coverage - ap.Coverage
					switch {
					case diff > 0:
						coverage += fmt.Sprintf(" (+%.1f%%)", diff)
					case diff < 0:
						coverage += fmt.Sprintf(" (%.1f%%)", diff)
					default:
						coverage += " (0.0%)"
					}
				} else {
					coverage += " (-)"
				}
			}
			if pkg.Summary.Action == parse.ActionPass && c.format != FormatMarkdown {
				switch cover := pkg.Coverage; {
				case cover > 0.0 && cover <= 50.0:
					coverage = c.red(coverage)
				case cover > 50.0 && cover < 80.0:
					coverage = c.yellow(coverage)
				case cover >= 80.0:
					coverage = c.green(coverage)
				}
			}
		}
		var status string
		switch pkg.Summary.Action {
		case parse.ActionPass:
			status = c.green("PASS")
		case parse.ActionFail:
			status = c.red("FAIL")
		default:
			status = strings.ToUpper(pkg.Summary.Action.String())
		}
		passed = append(passed, summaryRow{
			status,
			elapsed,
			packageName,
			coverage,
			strconv.Itoa(len(pkg.TestsByAction(parse.ActionPass))),
			strconv.Itoa(len(pkg.TestsByAction(parse.ActionFail))),
			strconv.Itoa(len(pkg.TestsByAction(parse.ActionSkip))),
		})
	}
	if tbl.NumRows() == 0 && len(passed) == 0 && len(notests) == 0 {
		return
	}
	for _, r := range passed {
		tbl.Row(r[:]...)
	}
