package app

import (
	"fmt"
	"sort"
	"strings"

	"github.com/tparse-clone/tparse/internal/lg"
	"github.com/tparse-clone/tparse/internal/parse"
)

func sortByElapsedDesc(tests []*parse.Test) {
	sort.Slice(tests, func(i, j int) bool {
		return tests[i].Elapsed() > tests[j].Elapsed()
	})
}

func (c *consoleWriter) styledHeader(status, pkg string) string {
	if c.format == FormatMarkdown {
		return "## " + c.red(status) + " • " + pkg
	}
	statusText := lg.NewStyle().Foreground(seqRed).Render(c.red(status))
	content := lg.JoinHorizontal(statusText, "  ", "package: "+pkg)
	return lg.NewStyle().
		BorderStyle(lg.ThickBorder).
		BorderForeground(seqBorder).
		Padding(0, 3).
		Render(content)
}

func (c *consoleWriter) divider() string {
	st := lg.NewStyle().BorderStyle(lg.NormalBorder).BorderTop(true).Width(c.width)
	if c.format != FormatMarkdown {
		st = st.Faint(true)
	}
	return st.Render("")
}

func (c *consoleWriter) printFailed(packages []*parse.Package) {
	for _, pkg := range packages {
		if pkg.HasPanic {
			fmt.Fprintln(c.w, c.styledPanic(pkg.Summary.Package, pkg.Summary.Test, pkg.PanicEvents))
			continue
		}
		failed := pkg.TestsByAction(parse.ActionFail)
		if len(failed) == 0 {
			continue
		}
		fmt.Fprintln(c.w, c.styledHeader(strings.ToUpper(pkg.Summary.Action.String()), pkg.Summary.Package))
		fmt.Fprintln(c.w)
		if c.format == FormatMarkdown {
			fmt.Fprintln(c.w, "```")
		}
		sort.Slice(failed, func(i, j int) bool { return failed[i].Name < failed[j].Name })
		var key string
		for i, t := range failed {
			base := parse.Base(t.Name)
			if i > 0 && key != base {
				fmt.Fprintln(c.w, c.divider())
			}
			key = base
			fmt.Fprintln(c.w, c.styledTest(t))
		}
		if c.format == FormatMarkdown {
			fmt.Fprintln(c.w, "```")
			fmt.Fprintln(c.w)
		}
	}
}

func (c *consoleWriter) styledPanic(pkgName, testName string, events []*parse.Event) string {
	if testName != "" {
		pkgName = pkgName + " • " + testName
	}
	header := c.styledHeader("PANIC", pkgName)
	var b strings.Builder
	for _, e := range events {
		b.WriteString(e.Output)
	}
	body := lg.NewStyle().Width(c.width).Render(b.String())
	return lg.JoinVertical(header, body)
}

func (c *consoleWriter) styledTest(t *parse.Test) string {
	t.SortEvents()
	var rows, headers []string
	for _, e := range t.Events {
		if e.Action != parse.ActionOutput {
			continue
		}
		if idx := strings.Index(e.Output, "--- FAIL: "); idx >= 0 {
			indent := strings.Count(e.Output[:idx], " ") / 2
			header := strings.Repeat(" ", indent) + strings.TrimSuffix(e.Output[idx:], "\n")
			headers = append(headers, lg.NewStyle().Foreground(seqDimRed).Render(header))
			continue
		}
		rows = append(rows, e.Output)
	}
	out := strings.Join(headers, "")
	body := strings.Join(rows, "")
	if body != "" {
		out += "\n\n" + body
	}
	return out
}
